package org.elide.events.domain.services;

import java.util.Collection;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.repository.NoRepositoryBean;

/**
 * Base of the Spring Data repositories: JpaRepository<Entity, Integer> + the small CRUD vocabulary used by the
 * business services (default methods over the Spring Data operations). Identities are generated by the database
 * when a new entity (null id) is added; an entity with an id is merged.
 *
 * Spring Data's own getById(...) returns a lazy reference and throws when the row is missing, so the services use
 * getByIdOrNull(...) instead.
 */
@NoRepositoryBean
public interface IEntityRepository<T> extends JpaRepository<T, Integer> {

	default T getByIdOrNull(Integer id) {
		return id == null ? null : findById(id).orElse(null);
	}

	default Collection<T> toCollection() {
		return findAll();
	}

	/** New entity (null id): INSERT, the identity is assigned; entity with an id: merged into the database. */
	default T add(T entity) {
		return save(entity);
	}

	/** Copies the state of a detached entity into the database (UPDATE) and returns the managed instance. */
	default T update(T entity) {
		return save(entity);
	}

	default boolean remove(T entity) {
		if (entity == null)
			return false;
		delete(entity); // cascades to the components of the aggregate
		return true;
	}

	default int size() {
		return (int) count();
	}
}
